import { useEffect, useState } from "react";
import Nav from "./components/Nav";
import Footer from "./components/Footer";
import Home from "./components/pages/Home";
import Avaliar from "./components/pages/Avaliar";
import Time from "./components/pages/Time";
import Leveling from "./components/pages/Leveling";
import Geridos from "./components/pages/Geridos";
import { supabase } from "./lib/supabase";
import { findManagerRule } from "./lib/hierarchy";

const ROUTES = ["home", "avaliar", "time", "leveling", "geridos"] as const;
type Route = (typeof ROUTES)[number];

function parseHash(): Route {
  const h = window.location.hash.replace(/^#\/?/, "").split("?")[0];
  if ((ROUTES as readonly string[]).includes(h)) return h as Route;
  return "home";
}

export default function App() {
  const [route, setRoute] = useState<Route>(() =>
    typeof window !== "undefined" ? parseHash() : "home",
  );
  const [isManager, setIsManager] = useState(false);

  useEffect(() => {
    const onHash = () => setRoute(parseHash());
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);

  useEffect(() => {
    (async () => {
      const { data } = await supabase.from("me").select("email").maybeSingle();
      const email = (data?.email as string | undefined) ?? null;
      setIsManager(!!findManagerRule(email));
    })();
  }, []);

  const go = (r: string) => {
    window.location.hash = "/" + r;
    window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior });
  };

  return (
    <div className="min-h-screen bg-white text-[#1A1A2E]">
      <Nav current={route} onNavigate={go} isManager={isManager} />
      <main>
        {route === "home" && <Home onNavigate={go} />}
        {route === "avaliar" && <Avaliar />}
        {route === "time" && <Time />}
        {route === "leveling" && <Leveling />}
        {route === "geridos" && <Geridos />}
      </main>
      <Footer />
    </div>
  );
}

