import { ITEMS, SEGMENTS, getSegment } from "../lib/data";
import { Scores } from "../lib/calc";

type Props = {
  scores: Scores;
  size?: number;
  centerLabel?: string;
  centerSub?: string;
  showCodes?: boolean;
};

const RING_INNER = 28;
const RING_OUTER = 150;
const RING_STEP = (RING_OUTER - RING_INNER) / 5;
const SLICE_DEG = 360 / 30;

function polar(cx: number, cy: number, r: number, deg: number) {
  const rad = ((deg - 90) * Math.PI) / 180;
  return [cx + r * Math.cos(rad), cy + r * Math.sin(rad)];
}

function arcPath(
  cx: number,
  cy: number,
  r1: number,
  r2: number,
  a1: number,
  a2: number,
) {
  const [x1, y1] = polar(cx, cy, r2, a1);
  const [x2, y2] = polar(cx, cy, r2, a2);
  const [x3, y3] = polar(cx, cy, r1, a2);
  const [x4, y4] = polar(cx, cy, r1, a1);
  const large = a2 - a1 > 180 ? 1 : 0;
  return `M ${x1} ${y1} A ${r2} ${r2} 0 ${large} 1 ${x2} ${y2} L ${x3} ${y3} A ${r1} ${r1} 0 ${large} 0 ${x4} ${y4} Z`;
}

export default function Wheel({
  scores,
  size = 380,
  centerLabel,
  centerSub,
  showCodes = true,
}: Props) {
  const cx = size / 2;
  const cy = size / 2;
  // escala para caber labels e índice
  const scale = size / 380;

  return (
    <svg
      viewBox={`0 0 ${380} ${380}`}
      width={size}
      height={size}
      style={{ display: "block" }}
    >
      {/* trilhas de fundo por fatia e anel */}
      {ITEMS.map((item, idx) => {
        const seg = getSegment(item.segment);
        const a1 = idx * SLICE_DEG;
        const a2 = a1 + SLICE_DEG;
        const score = scores[item.code] || 0;
        return (
          <g key={item.code}>
            {[1, 2, 3, 4, 5].map((lvl) => {
              const r1 = RING_INNER + (lvl - 1) * RING_STEP;
              const r2 = RING_INNER + lvl * RING_STEP;
              const filled = score >= lvl;
              return (
                <path
                  key={lvl}
                  d={arcPath(cx, cy, r1, r2, a1, a2)}
                  fill={seg.color}
                  opacity={filled ? 0.92 : 0.08}
                />
              );
            })}
            {/* separadores radiais finos */}
            <path
              d={arcPath(cx, cy, RING_INNER, RING_OUTER, a1, a1 + 0.3)}
              fill="#fff"
              opacity={0.9}
            />
          </g>
        );
      })}

      {/* código do item ao redor */}
      {showCodes &&
        ITEMS.map((item, idx) => {
          const a = idx * SLICE_DEG + SLICE_DEG / 2;
          const [tx, ty] = polar(cx, cy, RING_OUTER + 18, a);
          const seg = getSegment(item.segment);
          return (
            <text
              key={item.code}
              x={tx}
              y={ty}
              fontSize={10}
              fontWeight={600}
              fill={seg.color}
              textAnchor="middle"
              dominantBaseline="middle"
            >
              {item.code}
            </text>
          );
        })}

      {/* centro */}
      <circle cx={cx} cy={cy} r={RING_INNER - 2} fill="#1A1A2E" />
      {centerLabel && (
        <text
          x={cx}
          y={cy - (centerSub ? 4 : 0)}
          fill="#fff"
          fontSize={14}
          fontWeight={700}
          textAnchor="middle"
          dominantBaseline="middle"
        >
          {centerLabel}
        </text>
      )}
      {centerSub && (
        <text
          x={cx}
          y={cy + 10}
          fill="#fff"
          fontSize={7}
          opacity={0.75}
          textAnchor="middle"
          dominantBaseline="middle"
        >
          {centerSub}
        </text>
      )}
    </svg>
  );
}

export function WheelLegend() {
  return (
    <div className="flex flex-wrap gap-x-4 gap-y-2 text-xs">
      {SEGMENTS.map((s) => (
        <div key={s.id} className="flex items-center gap-2">
          <span
            className="inline-block w-2.5 h-2.5 rounded-full"
            style={{ background: s.color }}
          />
          <span className="text-slate-700">
            {s.id} · {s.short}
          </span>
        </div>
      ))}
    </div>
  );
}

// Para download: renderiza SVG grande e exporta como PNG
export function wheelToPngDataUrl(scores: Scores, centerLabel: string, centerSub: string, size = 1140): Promise<string> {
  return new Promise((resolve, reject) => {
    const scale = size / 380;
    // Construir SVG como string
    const cx = 190;
    const cy = 190;
    let paths = "";
    ITEMS.forEach((item, idx) => {
      const seg = getSegment(item.segment);
      const a1 = idx * SLICE_DEG;
      const a2 = a1 + SLICE_DEG;
      const score = scores[item.code] || 0;
      for (let lvl = 1; lvl <= 5; lvl++) {
        const r1 = RING_INNER + (lvl - 1) * RING_STEP;
        const r2 = RING_INNER + lvl * RING_STEP;
        const filled = score >= lvl;
        paths += `<path d="${arcPath(cx, cy, r1, r2, a1, a2)}" fill="${seg.color}" opacity="${filled ? 0.92 : 0.08}"/>`;
      }
      const a = idx * SLICE_DEG + SLICE_DEG / 2;
      const [tx, ty] = polar(cx, cy, RING_OUTER + 18, a);
      paths += `<text x="${tx}" y="${ty}" font-size="10" font-weight="600" fill="${seg.color}" text-anchor="middle" dominant-baseline="middle" font-family="system-ui, -apple-system, sans-serif">${item.code}</text>`;
    });
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 380" width="${size}" height="${size}">
      <rect width="380" height="380" fill="white"/>
      ${paths}
      <circle cx="${cx}" cy="${cy}" r="${RING_INNER - 2}" fill="#1A1A2E"/>
      <text x="${cx}" y="${cy - 4}" fill="white" font-size="14" font-weight="700" text-anchor="middle" dominant-baseline="middle" font-family="system-ui, sans-serif">${centerLabel}</text>
      <text x="${cx}" y="${cy + 10}" fill="white" font-size="7" opacity="0.75" text-anchor="middle" dominant-baseline="middle" font-family="system-ui, sans-serif">${centerSub}</text>
    </svg>`;

    const img = new Image();
    const blob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = size;
      canvas.height = size;
      const ctx = canvas.getContext("2d")!;
      ctx.fillStyle = "white";
      ctx.fillRect(0, 0, size, size);
      ctx.drawImage(img, 0, 0, size, size);
      URL.revokeObjectURL(url);
      resolve(canvas.toDataURL("image/png"));
    };
    img.onerror = (e) => {
      URL.revokeObjectURL(url);
      reject(e);
    };
    img.src = url;
  });
}

export function downloadPng(dataUrl: string, filename: string) {
  const a = document.createElement("a");
  a.href = dataUrl;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

