import { useEffect, useMemo, useState } from "react";
import { supabase } from "../../lib/supabase";
import {
  DISCIPLINES,
  ITEMS,
  SEGMENTS,
  getDiscipline,
  getSegment,
  Discipline,
} from "../../lib/data";
import {
  Scores,
  segmentAverage,
  simpleIndex,
  weightedIndex,
  levelOf,
  priorities,
  fmt,
} from "../../lib/calc";
import Wheel, { WheelLegend, wheelToPngDataUrl, downloadPng } from "../Wheel";
import { Download, RefreshCw } from "../Icons";

const MIN_RESPONSES = 8;

type Response = {
  id: number;
  person_name: string;
  career_level: string;
  discipline: string;
  scores: Scores;
  weighted_index: number;
  created_at: string;
};

export default function Time() {
  const [responses, setResponses] = useState<Response[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<"all" | Discipline>("all");
  const [email, setEmail] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    setError(null);
    const meRes = await supabase.from("me").select("email").maybeSingle();
    const em = meRes.data?.email as string | undefined;
    setEmail(em ?? null);
    if (!em || !em.toLowerCase().endsWith("@cora.com.br")) {
      setResponses([]);
      setLoading(false);
      return;
    }
    const { data, error } = await supabase
      .from("wheel_responses")
      .select("*")
      .order("created_at", { ascending: false });
    if (error) {
      setError(error.message);
    } else {
      setResponses((data as Response[]) ?? []);
    }
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, []);

  const allowed = email && email.toLowerCase().endsWith("@cora.com.br");

  const filtered = useMemo(() => {
    if (filter === "all") return responses;
    return responses.filter((r) => r.discipline === filter);
  }, [responses, filter]);

  const count = filtered.length;
  const hasEnough = count >= MIN_RESPONSES;

  // Média item a item
  const avgScores: Scores = useMemo(() => {
    const sums: Record<string, { total: number; n: number }> = {};
    for (const r of filtered) {
      for (const item of ITEMS) {
        const v = r.scores[item.code] || 0;
        if (v > 0) {
          sums[item.code] = sums[item.code] ?? { total: 0, n: 0 };
          sums[item.code].total += v;
          sums[item.code].n += 1;
        }
      }
    }
    const out: Scores = {};
    for (const code of Object.keys(sums)) {
      out[code] = sums[code].total / sums[code].n;
    }
    return out;
  }, [filtered]);

  // Índice do recorte: ponderado se filtro é cadeira, simples caso contrário
  const indexValue = useMemo(() => {
    if (!hasEnough) return null;
    if (filter === "all") return simpleIndex(avgScores);
    return weightedIndex(avgScores, filter as Discipline);
  }, [avgScores, filter, hasEnough]);

  const level = indexValue != null ? levelOf(indexValue) : null;
  const prios = useMemo(() => {
    if (!hasEnough) return [];
    const disc = filter === "all" ? "Generalista / Design Ops" : (filter as Discipline);
    return priorities(avgScores, disc);
  }, [avgScores, filter, hasEnough]);

  const centerLabel = indexValue != null ? fmt(indexValue) : "—";
  const centerSub = level ? `nível ${level.n}` : "";

  const handleDownload = async () => {
    const dataUrl = await wheelToPngDataUrl(
      avgScores,
      centerLabel,
      centerSub,
      1140,
    );
    const name = filter === "all" ? "time" : filter.toLowerCase().replace(/[^a-z]/g, "-");
    downloadPng(dataUrl, `roda-cora-ia-${name}.png`);
  };

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 py-10 sm:py-14">
      <header className="flex flex-wrap items-start justify-between gap-4 mb-8">
        <div>
          <p className="text-xs uppercase tracking-wider text-[#FE3E6D] font-semibold mb-3">
            Roda do time
          </p>
          <h1 className="text-3xl sm:text-4xl font-semibold text-[#1A1A2E] tracking-tight">
            Como estamos juntos
          </h1>
          <p className="mt-2 text-[#6B7085]">
            Média item a item. Diagnóstico de time, não avaliação de
            performance.
          </p>
        </div>
        <button
          onClick={load}
          className="shrink-0 px-4 py-2 rounded-full bg-[#F0F0F6] hover:bg-[#ECECF4] text-[#1A1A2E] text-sm transition active:scale-95 flex items-center gap-2"
        >
          <RefreshCw size={14} /> Atualizar
        </button>
      </header>

      {!allowed && !loading && (
        <div className="rounded-3xl bg-[#FFF0F4] border border-[#FE3E6D]/30 p-6 text-[#1A1A2E]">
          <p className="font-semibold mb-1">Acesso restrito a @cora.com.br</p>
          <p className="text-sm text-[#1A1A2E]/80">
            A roda do time só aparece para pessoas autenticadas com e-mail
            @cora.com.br. Faça login pelo SSO corporativo para continuar.
          </p>
        </div>
      )}

      {allowed && loading && (
        <p className="text-[#6B7085]">Carregando respostas...</p>
      )}

      {allowed && error && (
        <div className="rounded-2xl bg-[#FFF0F4] border border-[#FE3E6D]/30 p-4 text-[#FE3E6D] text-sm mb-6">
          Erro: {error}
        </div>
      )}

      {allowed && !loading && !error && (
        <>
          {/* Filtro por cadeira */}
          <div className="flex flex-wrap gap-2 mb-6">
            <FilterChip
              active={filter === "all"}
              onClick={() => setFilter("all")}
              label="Todas"
              count={responses.length}
            />
            {DISCIPLINES.map((d) => (
              <FilterChip
                key={d.id}
                active={filter === d.id}
                onClick={() => setFilter(d.id)}
                label={d.id}
                count={responses.filter((r) => r.discipline === d.id).length}
              />
            ))}
          </div>

          {!hasEnough ? (
            <div className="rounded-3xl bg-white border border-[#E6E6EF] p-8 text-center">
              <p className="text-sm text-[#6B7085] mb-3">
                {count} de {MIN_RESPONSES} respostas
              </p>
              <div className="h-2 w-full max-w-sm mx-auto bg-[#F0F0F6] rounded-full overflow-hidden mb-5">
                <div
                  className="h-full bg-[#FE3E6D] rounded-full transition-all"
                  style={{ width: `${Math.min(100, (count / MIN_RESPONSES) * 100)}%` }}
                />
              </div>
              <p className="font-medium text-[#1A1A2E] max-w-md mx-auto">
                A roda aparece quando pelo menos {MIN_RESPONSES} pessoas
                responderem.
              </p>
              <p className="text-sm text-[#6B7085] mt-2 max-w-md mx-auto">
                Assim ninguém fica exposto por ter preenchido primeiro.
              </p>
            </div>
          ) : (
            <>
              <div className="grid md:grid-cols-[1fr_1fr] gap-8 items-start">
                <div className="bg-white border border-[#E6E6EF] rounded-3xl p-5 flex flex-col items-center">
                  <Wheel
                    scores={avgScores}
                    size={340}
                    centerLabel={centerLabel}
                    centerSub={centerSub}
                  />
                  <div className="mt-5 w-full">
                    <WheelLegend />
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-3">
                    <div className="rounded-2xl p-4 border bg-white border-[#E6E6EF]">
                      <p className="text-xs uppercase tracking-wider text-[#6B7085]">
                        Respostas
                      </p>
                      <p className="text-3xl font-semibold text-[#1A1A2E] tabular-nums mt-1">
                        {count}
                      </p>
                    </div>
                    <div className="rounded-2xl p-4 border bg-[#FFF0F4] border-[#FE3E6D]/30">
                      <p className="text-xs uppercase tracking-wider text-[#6B7085]">
                        {filter === "all" ? "MRA-IA (média)" : "MRA-IA ponderado"}
                      </p>
                      <p className="text-3xl font-semibold text-[#1A1A2E] tabular-nums mt-1">
                        {fmt(indexValue)}
                      </p>
                    </div>
                  </div>
                  {level && (
                    <div className="bg-[#1A1A2E] text-white rounded-3xl p-5">
                      <p className="text-xs uppercase tracking-wider opacity-70">
                        Nível {level.n}
                      </p>
                      <p className="text-xl font-semibold mt-1">
                        {level.name} · {level.persona}
                      </p>
                    </div>
                  )}
                  <button
                    onClick={handleDownload}
                    className="w-full px-5 py-2.5 rounded-full bg-[#F0F0F6] hover:bg-[#ECECF4] text-[#1A1A2E] font-medium text-sm transition active:scale-95 flex items-center justify-center gap-2"
                  >
                    <Download size={16} /> Baixar roda do time
                  </button>
                </div>
              </div>

              {/* Médias por segmento */}
              <section className="mt-10">
                <h2 className="text-lg font-semibold text-[#1A1A2E] mb-3">
                  Médias por segmento
                </h2>
                <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
                  {SEGMENTS.map((s) => {
