{"path": "/components/SegmentIcon.tsx", "content": "import { Segment } from "../lib/data";

type Props = { segment: Segment; size?: number };

// Mini roda com a fatia do segmento destacada
export default function SegmentIcon({ segment, size = 32 }: Props) {
  const cx = 16;
  const cy = 16;
  const r = 13;
  // Posição de cada segmento (ordem S1..S6, 60° cada, começando no topo)
  const idx = parseInt(segment.id.replace("S", "")) - 1;
  const slice = 60;
  const a1 = idx * slice - 90;
  const a2 = a1 + slice;
  const rad = (d: number) => (d * Math.PI) / 180;
  const x1 = cx + r * Math.cos(rad(a1));
  const y1 = cy + r * Math.sin(rad(a1));
  const x2 = cx + r * Math.cos(rad(a2));
  const y2 = cy + r * Math.sin(rad(a2));
  const path = `M ${cx} ${cy} L ${x1} ${y1} A ${r} ${r} 0 0 1 ${x2} ${y2} Z`;
  return (
    <svg width={size} height={size} viewBox="0 0 32 32">
      <circle cx={cx} cy={cy} r={r} fill={segment.color} opacity={0.12} />
      <path d={path} fill={segment.color} />
      <circle cx={cx} cy={cy} r={r} fill="none" stroke={segment.color} strokeOpacity={0.4} />
    </svg>
  );
}
"}

