  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<"all" | Discipline>("all");
  const [email, setEmail] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    setError(null);
    const meRes = await supabase.from("me").select("email").maybeSingle();
    const em = meRes.data?.email as string | undefined;
    setEmail(em ?? null);
    if (!em || !em.toLowerCase().endsWith("@cora.com.br")) {
      setResponses([]);
      setLoading(false);
      return;
    }
    const { data, error } = await supabase
      .from("wheel_responses")
      .select("*")
      .order("created_at", { ascending: false });
    if (error) {
      setError(error.message);
    } else {
      setResponses((data as Response[]) ?? []);
    }
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, []);

  const allowed = email && email.toLowerCase().endsWith("@cora.com.br");

  const filtered = useMemo(() => {
    if (filter === "all") return responses;
    return responses.filter((r) => r.discipline === filter);
  }, [responses, filter]);

  const count = filtered.length;
  const hasEnough = count >= MIN_RESPONSES;

  // Média item a item
  const avgScores: Scores = useMemo(() => {
    const sums: Record<string, { total: number; n: number }> = {};
    for (const r of filtered) {
      for (const item of ITEMS) {
        const v = r.scores[item.code] || 0;
        if (v > 0) {
          sums[item.code] = sums[item.code] ?? { total: 0, n: 0 };
          sums[item.code].total += v;
          sums[item.code].n += 1;
        }
      }
    }
