                        <th className="text-left p-3 font-medium">Pessoa</th>
                        <th className="text-left p-3 font-medium">Cadeira</th>
                        <th className="text-left p-3 font-medium">
                          Senioridade
                        </th>
                        <th className="text-right p-3 font-medium">MRA-IA</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filtered.map((r) => (
                        <tr key={r.id} className="border-t border-[#E6E6EF]">
                          <td className="p-3 text-[#1A1A2E]">
                            {r.person_name}
                          </td>
                          <td className="p-3 text-[#6B7085]">
                            {r.discipline}
                          </td>
                          <td className="p-3 text-[#6B7085]">
                            {r.career_level}
                          </td>
                          <td className="p-3 text-right tabular-nums text-[#1A1A2E] font-medium">
                            {fmt(r.weighted_index)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </section>
            </>
          )}

          <p className="text-xs text-[#6B7085] text-center mt-10">
            Diagnóstico de time, não avaliação de performance.
          </p>
        </>
      )}
    </div>
  );
}

function FilterChip({
  active,
  onClick,
  label,
  count,
}: {
  active: boolean;
  onClick: () => void;
  label: string;
  count: number;
}) {
  return (
    <button
      onClick={onClick}
      className={`px-4 py-2 rounded-full text-sm transition active:scale-95 flex items-center gap-2 ${
        active
          ? "bg-[#1A1A2E] text-white"
          : "bg-white border border-[#E6E6EF] text-[#1A1A2E] hover:border-[#1A1A2E]/40"
      }`}
    >
      {label}
      <span
        className={`text-xs tabular-nums px-1.5 py-0.5 rounded-full ${active ? "bg-white/20" : "bg-[#F0F0F6] text-[#6B7085]"}`}
      >
        {count}
      </span>
    </button>
  );
}
"}

{"path": "/components/pages/Diamante.tsx", "content": "import { useEffect, useMemo, useState } from "react";
import { supabase } from "../../lib/supabase";
import { PHASES, USE_TYPES, SEED_DIAMOND } from "../../lib/data";
import { Plus, X, Link as LinkIcon, Trash, ChevronRight } from "../Icons";

type Item = {
  id: number;
  user_id: string;
  author_name: string;
  phase: string;
  type: string;
  what: string;
  tool: string | null;
  tool2: string | null;
  link: string | null;
  notes: string | null;
  created_at: string;
};

const typeColor = (t: string) => USE_TYPES.find((u) => u.id === t)?.color ?? "#6B7085";

export default function Diamante() {
  const [items, setItems] = useState<Item[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [email, setEmail] = useState<string | null>(null);
  const [userId, setUserId] = useState<string | null>(null);
  const [open, setOpen] = useState(false); // formulário colapsável
  const [opened, setOpened] = useState<Item | null>(null); // ficha
  const [seeding, setSeeding] = useState(false);

  const load = async () => {
    setLoading(true);
    setError(null);
    const meRes = await supabase.from("me").select("email, user_id").maybeSingle();
    const em = meRes.data?.email as string | undefined;
    const uid = meRes.data?.user_id as string | undefined;
    setEmail(em ?? null);
    setUserId(uid ?? null);
    const { data, error } = await supabase
      .from("diamond_items")
      .select("*")
      .order("created_at", { ascending: true });
    if (error) {
      setError(error.message);
    } else {
      const list = (data as Item[]) ?? [];
      setItems(list);
      // Seed se vazio e usuário autenticado @cora
      if (
        list.length === 0 &&
        em &&
        em.toLowerCase().endsWith("@cora.com.br") &&
        !seeding
      ) {
        setSeeding(true);
        const payload = SEED_DIAMOND.map((d) => ({
          author_name: "Cora Design",
          phase: d.phase,
          type: d.type,
          what: d.what,
          tool: d.tool ?? null,
          tool2: d.tool2 ?? null,
          link: null,
          notes: d.notes ?? null,
        }));
        const { error: insErr } = await supabase
          .from("diamond_items")
          .insert(payload);
        if (!insErr) {
          const r2 = await supabase
            .from("diamond_items")
            .select("*")
            .order("created_at", { ascending: true });
          setItems((r2.data as Item[]) ?? []);
        }
        setSeeding(false);
      }
    }
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, []);

  const allowed = !!email && email.toLowerCase().endsWith("@cora.com.br");

  const byPhase = useMemo(() => {
    const map: Record<string, Item[]> = {};
    for (const ph of PHASES) map[ph.id] = [];
    for (const it of items) {
      if (map[it.phase]) map[it.phase].push(it);
    }
    return map;
  }, [items]);

  const alpha = useMemo(
    () => [...items].sort((a, b) => a.what.localeCompare(b.what, "pt-BR")),
    [items],
  );

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 py-10 sm:py-14">
      <header className="mb-6">
        <p className="text-xs uppercase tracking-wider text-[#FE3E6D] font-semibold mb-3">
          Duplo Diamante
        </p>
        <h1 className="text-3xl sm:text-4xl font-semibold text-[#1A1A2E] tracking-tight">
          Como a IA aparece no nosso processo
        </h1>
        <p className="mt-2 text-[#6B7085] max-w-3xl">
          Mapa compartilhado dos usos reais de IA, do descobrir ao entregar.
          Enquanto a roda mede percepção, o diamante mostra a distribuição real.
        </p>
      </header>

      {/* Taxonomia */}
      <section className="rounded-3xl bg-[#F7F7FB] border border-[#E6E6EF] p-5 mb-8">
        <h3 className="font-semibold text-[#1A1A2E] mb-2 text-sm">
          Taxonomia Cora
        </h3>
        <p className="text-sm text-[#6B7085] mb-3">
          <strong className="text-[#1A1A2E]">Assistido</strong>: a IA turbina
          uma etapa que já existia. <strong className="text-[#1A1A2E]">Copiloto</strong>:
          a IA cocria, ancorada no dado. <strong className="text-[#1A1A2E]">First</strong>: a
          etapa só existe por causa da IA.
        </p>
        <div className="flex flex-wrap gap-2">
          {USE_TYPES.map((t) => (
            <span
              key={t.id}
              className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs text-white font-medium"
              style={{ background: t.color }}
            >
              {t.id}
            </span>
          ))}
        </div>
      </section>

      {/* Novo registro */}
      {allowed && (
        <section className="mb-8">
          <button
            onClick={() => setOpen((o) => !o)}
            className="w-full flex items-center justify-between gap-3 p-4 rounded-3xl bg-white border border-[#E6E6EF] hover:border-[#FE3E6D]/50 transition"
          >
            <span className="flex items-center gap-3">
              <span className="w-8 h-8 rounded-full bg-[#FFF0F4] text-[#FE3E6D] flex items-center justify-center">
                <Plus size={16} />
              </span>
              <span className="font-medium text-[#1A1A2E]">Novo registro</span>
            </span>
            <span className="text-sm text-[#6B7085]">
              {open ? "Fechar" : "Adicionar um uso de IA"}
            </span>
          </button>
          {open && (
            <NewItemForm
              userName={email?.split("@")[0] ?? ""}
              onCreated={async () => {
                setOpen(false);
                await load();
              }}
            />
          )}
        </section>
      )}

      {!allowed && !loading && (
        <div className="rounded-3xl bg-[#FFF0F4] border border-[#FE3E6D]/30 p-5 text-sm text-[#1A1A2E] mb-8">
          Faça login com e-mail @cora.com.br para criar novos registros. A
          leitura também exige acesso corporativo.
        </div>
      )}

      {loading && <p className="text-[#6B7085]">Carregando mapa...</p>}
      {error && (
        <div className="rounded-2xl bg-[#FFF0F4] border border-[#FE3E6D]/30 p-4 text-[#FE3E6D] text-sm mb-6">
          Erro: {error}
        </div>
      )}

      {/* Fases */}
      {!loading && !error && allowed && (
        <section className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
          {PHASES.map((ph) => (
            <div key={ph.id} className="min-w-0">
              <div className="flex items-baseline justify-between mb-3">
                <h3 className="font-semibold text-[#1A1A2E]">{ph.id}</h3>
                <span className="text-xs text-[#6B7085]">{ph.alt}</span>
              </div>
              <div className="space-y-3">
                {byPhase[ph.id].length === 0 && (
                  <div className="text-sm text-[#6B7085] bg-[#F7F7FB] border border-dashed border-[#E6E6EF] rounded-2xl p-4">
                    Nenhum registro ainda.
                  </div>
                )}
                {byPhase[ph.id].map((it) => (
                  <article
                    key={it.id}
                    className="bg-white border border-[#E6E6EF] rounded-3xl p-4"
                  >
                    <span
                      className="inline-block px-2 py-0.5 rounded-full text-[11px] text-white font-medium mb-2"
                      style={{ background: typeColor(it.type) }}
                    >
                      {it.type}
                    </span>
                    <p className="font-medium text-[#1A1A2E] leading-snug">
                      {it.what}
                    </p>
                    <div className="mt-2 flex flex-wrap items-center gap-1.5 text-xs text-[#6B7085]">
                      {it.tool && (
                        <span className="px-2 py-0.5 rounded-full bg-[#F0F0F6]">
                          {it.tool}
                        </span>
                      )}
                      {it.tool2 && (
                        <span className="px-2 py-0.5 rounded-full bg-[#F0F0F6]">
                          {it.tool2}
                        </span>
                      )}
                      {it.link && <LinkIcon size={12} />}
                    </div>
                    <button
                      onClick={() => setOpened(it)}
                      className="mt-3 text-xs text-[#FE3E6D] font-medium hover:underline flex items-center gap-0.5"
                    >
                      Abrir ficha <ChevronRight size={12} />
                    </button>
                  </article>
                ))}
              </div>
            </div>
          ))}
        </section>
      )}

      {/* Lista alfabética */}
      {!loading && allowed && items.length > 0 && (
        <section className="mt-14">
          <h2 className="text-lg font-semibold text-[#1A1A2E] mb-3">
            Todos os registros
          </h2>
          <div className="rounded-2xl border border-[#E6E6EF] bg-white divide-y divide-[#E6E6EF]">
            {alpha.map((it) => (
              <button
                key={it.id}
                onClick={() => setOpened(it)}
                className="w-full text-left p-3 flex items-center gap-3 hover:bg-[#F7F7FB] transition"
              >
                <span
                  className="shrink-0 w-2 h-2 rounded-full"
                  style={{ background: typeColor(it.type) }}
                />
                <span className="flex-1 min-w-0 text-sm text-[#1A1A2E] truncate">
                  {it.what}
                </span>
                <span className="text-xs text-[#6B7085]">{it.phase}</span>
              </button>
            ))}
          </div>
        </section>
      )}

      {/* Ficha (sheet) */}
      {opened && (
        <Sheet
          item={opened}
          currentUserId={userId}
          onClose={() => setOpened(null)}
          onDeleted={async () => {
            setOpened(null);
            await load();
          }}
        />
      )}
    </div>
  );
}

function NewItemForm({
  userName,
  onCreated,
}: {
  userName: string;
  onCreated: () => void;
}) {
  const [phase, setPhase] = useState(PHASES[0].id);
  const [type, setType] = useState(USE_TYPES[0].id);
  const [what, setWhat] = useState("");
  const [tool, setTool] = useState("");
  const [tool2, setTool2] = useState("");
  const [link, setLink] = useState("");
  const [notes, setNotes] = useState("");
  const [author, setAuthor] = useState(userName);
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const submit = async () => {
    if (!what.trim() || !author.trim()) return;
    setSaving(true);
    setErr(null);
    const { error } = await supabase.from("diamond_items").insert({
      author_name: author.trim(),
      phase,
      type,
      what: what.trim(),
      tool: tool.trim() || null,
      tool2: tool2.trim() || null,
      link: link.trim() || null,
      notes: notes.trim() || null,
    });
    setSaving(false);
    if (error) {
      setErr(error.message);
    } else {
      setWhat("");
      setTool("");
      setTool2("");
      setLink("");
      setNotes("");
      onCreated();
    }
  };

  return (
    <div className="mt-3 bg-white border border-[#E6E6EF] rounded-3xl p-5 space-y-4">
      <div className="grid sm:grid-cols-2 gap-3">
        <SelectField label="Fase" value={phase} onChange={setPhase}>
          {PHASES.map((p) => (
            <option key={p.id} value={p.id}>
              {p.id}
            </option>
          ))}
        </SelectField>
        <SelectField label="Tipo de uso" value={type} onChange={setType}>
          {USE_TYPES.map((t) => (
            <option key={t.id} value={t.id}>
              {t.id}
            </option>
          ))}
        </SelectField>
      </div>
      <TextField
        label="O que foi feito"
        value={what}
        onChange={setWhat}
        placeholder="Título curto"
      />
      <div className="grid sm:grid-cols-2 gap-3">
        <TextField
          label="Ferramenta 1"
          value={tool}
          onChange={setTool}
          placeholder="Ex.: ChatGPT"
        />
        <TextField
          label="Ferramenta 2"
          value={tool2}
          onChange={setTool2}
          placeholder="Opcional"
        />
      </div>
      <TextField
        label="Link"
        value={link}
        onChange={setLink}
        placeholder="https://..."
      />
      <div>
        <label className="block text-sm font-medium text-[#1A1A2E] mb-1.5">
          Notas
        </label>
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          rows={3}
          className="w-full px-3 py-2 rounded-2xl border border-[#E6E6EF] bg-white focus:outline-none focus:border-[#FE3E6D] text-[#1A1A2E] text-sm"
          placeholder="Como foi feito, o que funcionou, o que ficou pendente"
        />
      </div>
      <TextField
        label="Autor(a)"
        value={author}
        onChange={setAuthor}
        placeholder="Seu nome"
      />
      {err && <p className="text-sm text-[#FE3E6D]">Erro: {err}</p>}
      <button
        onClick={submit}
        disabled={saving || !what.trim() || !author.trim()}
        className="px-5 py-2.5 rounded-full bg-[#FE3E6D] hover:bg-[#D92A56] text-white font-medium text-sm transition active:scale-95 disabled:opacity-50"
      >
        {saving ? "Salvando..." : "Adicionar ao mapa"}
      </button>
    </div>
  );
}

function TextField({
  label,
  value,
  onChange,
  placeholder,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
}) {
  return (
    <div>
      <label className="block text-sm font-medium text-[#1A1A2E] mb-1.5">
        {label}
      </label>
      <input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="w-full px-3 py-2 rounded-2xl border border-[#E6E6EF] bg-white focus:outline-none focus:border-[#FE3E6D] text-[#1A1A2E] text-sm"
      />
    </div>
  );
}

function SelectField({
  label,
  value,
  onChange,
  children,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  children: React.ReactNode;
}) {
  return (
    <div>
      <label className="block text-sm font-medium text-[#1A1A2E] mb-1.5">
        {label}
      </label>
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full px-3 py-2 rounded-2xl border border-[#E6E6EF] bg-white focus:outline-none focus:border-[#FE3E6D] text-[#1A1A2E] text-sm"
      >
        {children}
      </select>
    </div>
  );
}

function Sheet({
  item,
  currentUserId,
  onClose,
  onDeleted,
}: {
  item: Item;
  currentUserId: string | null;
  onClose: () => void;
  onDeleted: () => void;
}) {
  const [deleting, setDeleting] = useState(false);
  const canDelete = currentUserId && currentUserId === item.user_id;

  const handleDelete = async () => {
    if (!confirm("Excluir este registro?")) return;
    setDeleting(true);
    const { error } = await supabase
      .from("diamond_items")
      .delete()
      .eq("id", item.id);
    setDeleting(false);
    if (!error) onDeleted();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex justify-end"
      onClick={onClose}
    >
      <div className="absolute inset-0 bg-black/30" />
      <div
        className="relative w-full sm:max-w-md bg-white h-full overflow-y-auto p-6 shadow-xl"
        onClick={(e) => e.stopPropagation()}
      >
        <button
          onClick={onClose}
          className="absolute top-4 right-4 w-8 h-8 rounded-full bg-[#F0F0F6] hover:bg-[#ECECF4] flex items-center justify-center text-[#1A1A2E]"
        >
          <X size={16} />
        </button>
        <span
          className="inline-block px-2 py-0.5 rounded-full text-[11px] text-white font-medium mb-3"
          style={{ background: typeColor(item.type) }}
        >
          {item.type}
        </span>
        <h3 className="text-xl font-semibold text-[#1A1A2E] leading-tight mb-1">
          {item.what}
        </h3>
        <p className="text-sm text-[#6B7085] mb-6">Fase: {item.phase}</p>
        {item.notes && (
          <div className="mb-5">
            <p className="text-xs uppercase tracking-wider text-[#6B7085] mb-1">
              Como foi feito
            </p>
            <p className="text-sm text-[#1A1A2E] leading-relaxed whitespace-pre-wrap">
              {item.notes}
            </p>
          </div>
        )}
        <div className="mb-5">
          <p className="text-xs uppercase tracking-wider text-[#6B7085] mb-1.5">
            Ferramentas
          </p>
          <div className="flex flex-wrap gap-2">
            {item.tool && (
              <span className="px-2.5 py-1 rounded-full bg-[#F0F0F6] text-xs">
                {item.tool}
              </span>
            )}
            {item.tool2 && (
              <span className="px-2.5 py-1 rounded-full bg-[#F0F0F6] text-xs">
                {item.tool2}
              </span>
            )}
            {!item.tool && !item.tool2 && (
              <span className="text-xs text-[#6B7085]">—</span>
            )}
          </div>
        </div>
        {item.link && (
          <div className="mb-5">
            <p className="text-xs uppercase tracking-wider text-[#6B7085] mb-1">
              Link
            </p>
            <a
              href={item.link}
              target="_blank"
              rel="noreferrer"
              className="text-sm text-[#FE3E6D] hover:underline break-all flex items-center gap-1"
            >
              <LinkIcon size={14} /> {item.link}
            </a>
          </div>
        )}
        <div className="pt-5 border-t border-[#E6E6EF] text-xs text-[#6B7085]">
          <p>
            Por {item.author_name} · {new Date(item.created_at).toLocaleDateString("pt-BR", { day: "2-digit", month: "short", year: "numeric" })}
          </p>
        </div>
        {canDelete && (
          <button
            onClick={handleDelete}
            disabled={deleting}
            className="mt-5 px-4 py-2 rounded-full text-[#FE3E6D] hover:bg-[#FFF0F4] text-sm font-medium transition flex items-center gap-2"
          >
            <Trash size={14} /> {deleting ? "Excluindo..." : "Excluir registro"}
          </button>
        )}
      </div>
    </div>
  );
}
"}

{"path": "/App.tsx", "content": "import { useEffect, useState } from "react";
import Nav from "./components/Nav";
import Footer from "./components/Footer";
import Home from "./components/pages/Home";
import Avaliar from "./components/pages/Avaliar";
import Time from "./components/pages/Time";
import Leveling from "./components/pages/Leveling";
import Diamante from "./components/pages/Diamante";

const ROUTES = ["home", "avaliar", "time", "leveling", "diamante"] as const;
type Route = (typeof ROUTES)[number];

function parseHash(): Route {
  const h = window.location.hash.replace(/^#\/?/, "").split("?")[0];
  if ((ROUTES as readonly string[]).includes(h)) return h as Route;
  return "home";
}

export default function App() {
  const [route, setRoute] = useState<Route>(() =>
    typeof window !== "undefined" ? parseHash() : "home",
  );

  useEffect(() => {
    const onHash = () => setRoute(parseHash());
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);

  const go = (r: string) => {
    window.location.hash = "/" + r;
    window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior });
  };

  return (
    <div className="min-h-screen bg-white text-[#1A1A2E]">
      <Nav current={route} onNavigate={go} />
      <main>
        {route === "home" && <Home onNavigate={go} />}
        {route === "avaliar" && <Avaliar />}
        {route === "time" && <Time />}
        {route === "leveling" && <Leveling />}
        {route === "diamante" && <Diamante />}
      </main>
      <Footer />
    </div>
  );
}
"}

