type Draft = {
  name: string;
  discipline: Discipline | "";
  seniority: SeniorityLevel | "";
  scores: Scores;
};

const emptyDraft: Draft = {
  name: "",
  discipline: "",
  seniority: "",
  scores: {},
};

export default function Avaliar() {
  const [draft, setDraft] = useState<Draft>(emptyDraft);
  const [step, setStep] = useState(0); // 0 = identificação, 1..6 = segmentos, 7 = resultado
  const [loaded, setLoaded] = useState(false);
  const [sending, setSending] = useState(false);
  const [sendMsg, setSendMsg] = useState<string | null>(null);
  const [sendErr, setSendErr] = useState<string | null>(null);

  // carregar rascunho
  useEffect(() => {
    try {
      const raw = localStorage.getItem(DRAFT_KEY);
      if (raw) setDraft({ ...emptyDraft, ...JSON.parse(raw) });
    } catch {}
    setLoaded(true);
  }, []);

  // salvar rascunho
  useEffect(() => {
    if (!loaded) return;
    localStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
  }, [draft, loaded]);

  const setScore = (code: string, v: number) => {
    setDraft((d) => ({ ...d, scores: { ...d.scores, [code]: v } }));
    // Avançar sozinho se completou todos os itens do segmento atual
    if (step >= 1 && step <= 6) {
      const seg = SEGMENTS[step - 1];
      const segItems = ITEMS.filter((i) => i.segment === seg.id);
      const next = { ...draft.scores, [code]: v };
      const allAnswered = segItems.every((i) => (next[i.code] || 0) > 0);
      const isLastOfSeg = segItems[segItems.length - 1].code === code;
      if (allAnswered && isLastOfSeg) {
        setTimeout(() => setStep((s) => Math.min(7, s + 1)), 250);
      }
    }
  };

  const canAdvanceId =
    draft.name.trim().length > 0 && draft.discipline && draft.seniority;

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 py-8 sm:py-12">
      {/* Stepper */}
      {step < 7 && (
        <div className="mb-8">
          <div className="flex items-center justify-between mb-3">
            <p className="text-xs uppercase tracking-wider text-[#6B7085]">
              {step === 0
                ? "Etapa 1 de 7 · Identificação"
                : `Etapa ${step + 1} de 7 · ${SEGMENTS[step - 1].id} ${SEGMENTS[step - 1].title}`}
            </p>
            <p className="text-xs text-[#6B7085]">
              {answeredCount(draft.scores)} de 30 itens
            </p>
          </div>
          <div className="h-1.5 bg-[#F0F0F6] rounded-full overflow-hidden">
            <div
              className="h-full bg-[#FE3E6D] rounded-full transition-all"
              style={{ width: `${((step + 1) / 7) * 100}%` }}
            />
          </div>
          <div className="mt-3 flex gap-1">
            {[0, 1, 2, 3, 4, 5, 6].map((n) => (
              <button
                key={n}
                onClick={() => (n === 0 || canAdvanceId) && setStep(n)}
                className={`h-1.5 flex-1 rounded-full transition ${
                  step === n
                    ? "bg-[#1A1A2E]"
                    : step > n
                      ? "bg-[#FE3E6D]/60"
                      : "bg-[#F0F0F6]"
                }`}
                aria-label={`Ir para etapa ${n + 1}`}
              />
            ))}
          </div>
        </div>
      )}

      {step === 0 && (
        <IdentificationStep
          draft={draft}
          onChange={setDraft}
          onNext={() => canAdvanceId && setStep(1)}
        />
      )}

      {step >= 1 && step <= 6 && (
        <SegmentStep
          seg={SEGMENTS[step - 1]}
          scores={draft.scores}
          onScore={setScore}
          onBack={() => setStep(step - 1)}
          onNext={() => setStep(step + 1)}
        />
      )}

      {step === 7 && (
        <ResultStep
          draft={draft}
          onBack={() => setStep(6)}
          sending={sending}
          sendMsg={sendMsg}
          sendErr={sendErr}
          onSend={async () => {
            setSendErr(null);
            setSendMsg(null);
            setSending(true);
            // Validar domínio pela view me
            const meRes = await supabase.from("me").select("email").maybeSingle();
            const email = meRes.data?.email as string | undefined;
            if (!email || !email.toLowerCase().endsWith("@cora.com.br")) {
              setSendErr(
                "Envio ao time exige e-mail @cora.com.br. Seu acesso atual não permite salvar.",
              );
              setSending(false);
              return;
            }
            const widx = weightedIndex(draft.scores, draft.discipline as Discipline);
            const payload = {
              person_name: draft.name.trim(),
              career_level: draft.seniority,
              discipline: draft.discipline,
              scores: draft.scores,
              weighted_index: widx ?? 0,
            };
            const { error } = await supabase
              .from("wheel_responses")
              .insert(payload);
            if (error) {
              setSendErr("Não foi possível enviar: " + error.message);
            } else {
              setSendMsg("Enviado! Sua resposta já alimenta a roda do time.");
            }
            setSending(false);
          }}
          onSaveLocal={() => {
            try {
              const raw = localStorage.getItem(HISTORY_KEY);
              const list = raw ? JSON.parse(raw) : [];
              list.push({ ...draft, savedAt: new Date().toISOString() });
              localStorage.setItem(HISTORY_KEY, JSON.stringify(list));
              setSendMsg("Salvo no seu histórico local (navegador).");
            } catch {
              setSendErr("Não foi possível salvar no navegador.");
            }
          }}
        />
      )}
    </div>
  );
}

function IdentificationStep({
  draft,
  onChange,
  onNext,
}: {
  draft: Draft;
  onChange: (d: Draft) => void;
  onNext: () => void;
}) {
  return (
    <div>
      <h1 className="text-3xl sm:text-4xl font-semibold text-[#1A1A2E] tracking-tight">
        Antes de começar
      </h1>
      <p className="mt-3 text-[#6B7085]">
        Isso define os pesos e a faixa de comparação. Dá para mudar depois.
      </p>
      <div className="mt-8 space-y-5">
        <Field label="Como você se chama?">
          <input
            type="text"
            value={draft.name}
            onChange={(e) => onChange({ ...draft, name: e.target.value })}
            placeholder="Nome e sobrenome"
            className="w-full px-4 py-3 rounded-2xl border border-[#E6E6EF] bg-white focus:outline-none focus:border-[#FE3E6D] text-[#1A1A2E]"
          />
        </Field>
        <Field label="Qual sua cadeira?">
          <div className="grid sm:grid-cols-2 gap-2">
            {DISCIPLINES.map((d) => {
              const active = draft.discipline === d.id;
              return (
                <button
                  key={d.id}
                  onClick={() => onChange({ ...draft, discipline: d.id })}
                  className={`text-left p-4 rounded-2xl border transition active:scale-[0.99] ${
                    active
                      ? "bg-[#FFF0F4] border-[#FE3E6D]"
                      : "bg-white border-[#E6E6EF] hover:border-[#1A1A2E]/20"
                  }`}
                >
                  <p className="font-medium text-[#1A1A2E]">{d.id}</p>
                  <p className="text-xs text-[#6B7085] mt-1">{d.focus}</p>
                </button>
              );
            })}
          </div>
        </Field>
        <Field label="Qual seu nível de senioridade?">
          <div className="flex flex-wrap gap-2">
            {SENIORITY.map((s) => {
              const active = draft.seniority === s.id;
              return (
                <button
                  key={s.id}
                  onClick={() => onChange({ ...draft, seniority: s.id })}
                  className={`px-4 py-2 rounded-full text-sm transition active:scale-95 ${
                    active
                      ? "bg-[#1A1A2E] text-white"
                      : "bg-white border border-[#E6E6EF] text-[#1A1A2E] hover:border-[#1A1A2E]/40"
                  }`}
                >
                  {s.id}
                </button>
              );
            })}
          </div>
        </Field>
      </div>
      <div className="mt-10">
        <button
          onClick={onNext}
          disabled={
            !(draft.name.trim() && draft.discipline && draft.seniority)
          }
          className="px-5 py-2.5 rounded-full bg-[#FE3E6D] hover:bg-[#D92A56] text-white font-medium text-sm transition active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed"
        >
          Começar
        </button>
      </div>
    </div>
  );
}

function Field({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <label className="block text-sm font-medium text-[#1A1A2E] mb-2">
        {label}
      </label>
      {children}
    </div>
  );
}

function SegmentStep({
  seg,
  scores,
  onScore,
  onBack,
  onNext,
}: {
  seg: ReturnType<typeof getSegment>;
  scores: Scores;
  onScore: (c: string, v: number) => void;
  onBack: () => void;
  onNext: () => void;
}) {
  const items = ITEMS.filter((i) => i.segment === seg.id);
  const answered = items.filter((i) => (scores[i.code] || 0) > 0).length;
  return (
    <div>
      <div
        className="rounded-3xl p-5 border border-[#E6E6EF] mb-6"
        style={{ background: seg.bg }}
      >
        <div className="flex items-start gap-3">
          <SegmentIcon segment={seg} size={44} />
          <div>
            <p
              className="text-xs font-semibold tracking-wide"
              style={{ color: seg.color }}
            >
              {seg.id} · {answered}/{items.length} respondidos
            </p>
            <h2 className="text-xl font-semibold text-[#1A1A2E] leading-tight">
              {seg.title}
            </h2>
            <p className="mt-2 text-sm text-[#1A1A2E]/80">{seg.description}</p>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        {items.map((item) => {
          const score = scores[item.code] || 0;
          return (
            <div
              key={item.code}
              className="bg-white border border-[#E6E6EF] rounded-3xl p-5"
            >
              <div className="flex items-baseline gap-3 mb-1">
                <span
                  className="text-xs font-semibold tabular-nums"
                  style={{ color: seg.color }}
                >
                  {item.code}
                </span>
                <h3 className="font-semibold text-[#1A1A2E] text-lg leading-snug">
                  {item.title}
                </h3>
              </div>
              <p className="text-sm text-[#6B7085] mb-4">{item.description}</p>
              <div className="space-y-2">
                {item.levels.map((desc, idx) => {
                  const n = idx + 1;
                  const active = score === n;
                  return (
                    <button
                      key={n}
                      onClick={() => onScore(item.code, n)}
                      className={`w-full text-left p-3 rounded-2xl border transition active:scale-[0.99] flex items-start gap-3 ${
                        active
                          ? "border-[#FE3E6D] bg-[#FFF0F4]"
                          : "border-[#E6E6EF] hover:border-[#1A1A2E]/30 bg-white"
                      }`}
                    >
                      <span
                        className={`shrink-0 w-7 h-7 rounded-full flex items-center justify-center text-xs font-semibold ${
                          active
                            ? "bg-[#FE3E6D] text-white"
                            : "bg-[#F0F0F6] text-[#6B7085]"
                        }`}
                      >
                        {active ? <Check size={14} /> : n}
                      </span>
                      <span className="text-sm text-[#1A1A2E] leading-relaxed pt-0.5">
                        {desc}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>

      <div className="mt-8 flex justify-between gap-3">
        <button
          onClick={onBack}
          className="px-4 py-2.5 rounded-full bg-[#F0F0F6] hover:bg-[#ECECF4] text-[#1A1A2E] font-medium text-sm transition active:scale-95 flex items-center gap-1"
        >
          <ChevronLeft size={16} /> Voltar
        </button>
        <button
          onClick={onNext}
          className="px-5 py-2.5 rounded-full bg-[#1A1A2E] hover:bg-[#1A1A2E]/90 text-white font-medium text-sm transition active:scale-95 flex items-center gap-1"
        >
          Próximo <ChevronRight size={16} />
        </button>
      </div>
    </div>
  );
}

function ResultStep({
  draft,
  onBack,
  onSend,
  onSaveLocal,
  sending,
  sendMsg,
  sendErr,
}: {
  draft: Draft;
  onBack: () => void;
  onSend: () => void;
  onSaveLocal: () => void;
  sending: boolean;
  sendMsg: string | null;
  sendErr: string | null;
}) {
  const discipline = draft.discipline as Discipline;
  const seniority = draft.seniority as SeniorityLevel;
  const simple = simpleIndex(draft.scores);
  const widx = weightedIndex(draft.scores, discipline);
  const answered = answeredCount(draft.scores);
  const level = widx != null ? levelOf(widx) : null;
  const prios = priorities(draft.scores, discipline);
  const fb = widx != null ? seniorityFeedback(widx, seniority, answered) : null;

  const centerLabel = widx != null ? fmt(widx) : "—";
  const centerSub = level ? `nível ${level.n}` : "";

  const handleDownload = async () => {
    const dataUrl = await wheelToPngDataUrl(
      draft.scores,
      centerLabel,
      centerSub,
      1140,
    );
    const safeName = draft.name.trim().replace(/\s+/g, "-").toLowerCase() || "roda";
    downloadPng(dataUrl, `roda-cora-ia-${safeName}.png`);
  };

  return (
    <div>
      <p className="text-xs uppercase tracking-wider text-[#FE3E6D] font-semibold mb-3">
        Resultado
      </p>
      <h1 className="text-3xl sm:text-4xl font-semibold text-[#1A1A2E] tracking-tight">
        A sua roda, {draft.name.split(" ")[0]}.
      </h1>
      <p className="mt-2 text-[#6B7085]">
        {discipline} · {seniority} · {answered} de 30 itens respondidos
      </p>

      <div className="mt-8 grid md:grid-cols-[1fr_1fr] gap-8 items-start">
        <div className="bg-white border border-[#E6E6EF] rounded-3xl p-5 flex flex-col items-center">
          <Wheel
            scores={draft.scores}
            size={340}
            centerLabel={centerLabel}
            centerSub={centerSub}
          />
          <div className="mt-5 w-full">
            <WheelLegend />
          </div>
        </div>

        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <Stat label="MRA-IA simples" value={fmt(simple)} />
            <Stat label="MRA-IA ponderado" value={fmt(widx)} highlight />
          </div>
          {level && (
            <div className="bg-[#1A1A2E] text-white rounded-3xl p-5">
              <p className="text-xs uppercase tracking-wider opacity-70">
                Nível {level.n}
              </p>
              <p className="text-xl font-semibold mt-1">
                {level.name} · {level.persona}
              </p>
              <p className="text-sm opacity-80 mt-2 leading-relaxed">
                {level.desc}
              </p>
            </div>
          )}
          {fb && (
            <div
              className={`rounded-2xl p-4 text-sm leading-relaxed ${
                fb.status === "dentro"
                  ? "bg-[#EAF7EC] text-[#1A1A2E] border border-[#43A047]/30"
                  : fb.status === "abaixo"
                    ? "bg-[#FFF0F4] text-[#1A1A2E] border border-[#FE3E6D]/30"
                    : "bg-[#EAF5FC] text-[#1A1A2E] border border-[#2D9CDB]/30"
              }`}
            >
              {fb.text}
            </div>
          )}
        </div>
      </div>

      {/* Médias por segmento */}
      <section className="mt-10">
        <h2 className="text-lg font-semibold text-[#1A1A2E] mb-3">
          Médias por segmento
        </h2>
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {SEGMENTS.map((s) => {
            const avg = segmentAverage(draft.scores, s.id);
            const pct = avg ? (avg / 5) * 100 : 0;
            return (
              <div
                key={s.id}
                className="bg-white border border-[#E6E6EF] rounded-2xl p-4"
              >
                <div className="flex items-center justify-between mb-2">
                  <span
                    className="text-xs font-semibold"
                    style={{ color: s.color }}
                  >
                    {s.id} · {s.short}
                  </span>
                  <span className="text-sm font-semibold tabular-nums text-[#1A1A2E]">
                    {fmt(avg)}
                  </span>
                </div>
                <div className="h-1.5 bg-[#F0F0F6] rounded-full overflow-hidden">
                  <div
                    className="h-full rounded-full"
                    style={{ width: `${pct}%`, background: s.color }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      </section>

      {/* Prioridades */}
      {prios.length > 0 && (
        <section className="mt-10">
          <h2 className="text-lg font-semibold text-[#1A1A2E] mb-1">
            3 prioridades de desenvolvimento
          </h2>
          <p className="text-sm text-[#6B7085] mb-4">
            Ordenadas por nota ÷ peso do segmento. Nota baixa em segmento de
            peso alto sobe primeiro.
          </p>
          <div className="space-y-3">
            {prios.map((p, i) => {
              const seg = getSegment(p.item.segment);
              return (
                <div
                  key={p.item.code}
                  className="bg-white border border-[#E6E6EF] rounded-3xl p-5"
                >
                  <div className="flex items-baseline gap-3 mb-2">
                    <span
                      className="shrink-0 w-7 h-7 rounded-full bg-[#1A1A2E] text-white flex items-center justify-center text-xs font-semibold"
                    >
                      {i + 1}
                    </span>
                    <div className="min-w-0">
                      <p
                        className="text-xs font-semibold"
                        style={{ color: seg.color }}
                      >
                        {p.item.code} · {seg.short}
                      </p>
                      <p className="font-semibold text-[#1A1A2E]">
                        {p.item.title}
                      </p>
                    </div>
                    <span className="ml-auto shrink-0 text-sm text-[#6B7085] tabular-nums">
                      nota {p.score}
                    </span>
                  </div>
                  <p className="text-xs uppercase tracking-wider text-[#6B7085] mt-3 mb-1">
                    Próximo passo (nível {p.next})
                  </p>
                  <p className="text-sm text-[#1A1A2E] leading-relaxed">
                    {p.nextDesc}
                  </p>
                </div>
              );
            })}
          </div>
        </section>
      )}

      {/* Ações */}
      <section className="mt-10">
        <div className="flex flex-wrap gap-3">
          <button
            onClick={handleDownload}
            className="px-5 py-2.5 rounded-full bg-[#1A1A2E] text-white hover:bg-[#1A1A2E]/90 font-medium text-sm transition active:scale-95 flex items-center gap-2"
          >
            <Download size={16} /> Baixar minha roda
          </button>
          <button
            onClick={onSaveLocal}
            className="px-5 py-2.5 rounded-full bg-[#F0F0F6] hover:bg-[#ECECF4] text-[#1A1A2E] font-medium text-sm transition active:scale-95"
          >
            Salvar no histórico local
          </button>
          <button
            onClick={onSend}
            disabled={sending}
            className="px-5 py-2.5 rounded-full bg-[#FE3E6D] hover:bg-[#D92A56] text-white font-medium text-sm transition active:scale-95 disabled:opacity-50"
          >
            {sending ? "Enviando..." : "Enviar para o time"}
          </button>
          <button
            onClick={onBack}
            className="px-4 py-2.5 rounded-full text-[#6B7085] hover:text-[#1A1A2E] text-sm transition"
          >
            Voltar e revisar
          </button>
        </div>
        {sendMsg && (
          <p className="mt-3 text-sm text-[#43A047]">{sendMsg}</p>
        )}
        {sendErr && (
          <p className="mt-3 text-sm text-[#FE3E6D]">{sendErr}</p>
        )}
      </section>
    </div>
  );
}

function Stat({
  label,
  value,
  highlight,
}: {
  label: string;
  value: string;
  highlight?: boolean;
}) {
  return (
    <div
      className={`rounded-2xl p-4 border ${highlight ? "bg-[#FFF0F4] border-[#FE3E6D]/30" : "bg-white border-[#E6E6EF]"}`}
    >
      <p className="text-xs uppercase tracking-wider text-[#6B7085]">{label}</p>
      <p className="text-3xl font-semibold text-[#1A1A2E] tabular-nums mt-1">
        {value}
      </p>
    </div>
  );
}

