{"path": "/lib/hierarchy.ts", "content": "// Hierarquia gestor → geridos.
// Casamento por substring (case-insensitive). O e-mail do gestor pode conter
// "ferre" (ex.: joao.ferreira@cora.com.br); os geridos são identificados pelo
// person_name que a pessoa digita ao preencher a roda (ex.: "Bruna Alves" bate
// com "bruna").
//
// Regra especial: se "all" aparecer na lista de geridos, o gestor vê todo
// mundo que respondeu.

export type ManagerRule = {
  managerMatch: string; // substring no e-mail
  manages: string[]; // substrings no person_name, ou ["all"]
  label: string; // como aparece no cabeçalho da aba
};

export const MANAGER_RULES: ManagerRule[] = [
  {
    managerMatch: "leticia",
    manages: ["all"],
    label: "Toda a área",
  },
  {
    managerMatch: "ferre",
    manages: ["bruna", "felipe castro", "fernanda", "thaise"],
    label: "Seu time",
  },
  {
    managerMatch: "aura",
    manages: ["julia"],
    label: "Seu time",
  },
  {
    managerMatch: "portella",
    manages: ["paulino"],
    label: "Seu time",
  },
];

export function findManagerRule(email: string | null): ManagerRule | null {
  if (!email) return null;
  const e = email.toLowerCase();
  // "leticia" ganha prioridade (vê todo mundo) mesmo se bater outra regra
  const all = MANAGER_RULES.find(
    (r) => r.manages.includes("all") && e.includes(r.managerMatch),
  );
  if (all) return all;
  return MANAGER_RULES.find((r) => e.includes(r.managerMatch)) ?? null;
}

// Decide se um person_name pertence aos geridos da regra
export function isManagedBy(personName: string, rule: ManagerRule): boolean {
  if (rule.manages.includes("all")) return true;
  const n = personName.toLowerCase();
  return rule.manages.some((frag) => n.includes(frag.toLowerCase()));
}
"}

{"path": "/components/pages/Geridos.tsx", "content": "import { useEffect, useMemo, useState } from "react";
import { supabase } from "../../lib/supabase";
import {
  SEGMENTS,
  LEVELS,
  Discipline,
  getSegment,
} from "../../lib/data";
import {
  Scores,
  segmentAverage,
  weightedIndex,
  levelOf,
  priorities,
} from "../../lib/calc";
import Wheel, { WheelLegend } from "../Wheel";
import { ChevronLeft, ChevronRight } from "../Icons";
import { findManagerRule, isManagedBy, ManagerRule } from "../../lib/hierarchy";

type Response = {
  id: number;
  person_name: string;
  career_level: string;
  discipline: string;
  scores: Scores;
  weighted_index: number;
  created_at: string;
};

export default function Geridos() {
  const [email, setEmail] = useState<string | null>(null);
  const [rule, setRule] = useState<ManagerRule | null>(null);
  const [responses, setResponses] = useState<Response[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<Response | null>(null);

  useEffect(() => {
    (async () => {
      setLoading(true);
      setError(null);
      const meRes = await supabase.from("me").select("email").maybeSingle();
      const em = (meRes.data?.email as string | undefined) ?? null;
      setEmail(em);
      const r = findManagerRule(em);
      setRule(r);
      if (!r) {
        setLoading(false);
        return;
      }
      const { data, error } = await supabase
        .from("wheel_responses")
        .select("*")
        .order("created_at", { ascending: false });
      if (error) {
        setError(error.message);
      } else {
        setResponses((data as Response[]) ?? []);
      }
      setLoading(false);
    })();
  }, []);

  // Mantém só o envio mais recente de cada pessoa
  const latestByPerson = useMemo(() => {
    const map = new Map<string, Response>();
    for (const r of responses) {
      const key = r.person_name.trim().toLowerCase();
      if (!map.has(key)) map.set(key, r); // já vem ordenado desc
    }
    return [...map.values()];
  }, [responses]);

  const managed = useMemo(() => {
    if (!rule) return [];
    return latestByPerson.filter((r) => isManagedBy(r.person_name, rule));
  }, [latestByPerson, rule]);

  if (loading) {
    return (
      <div className="max-w-6xl mx-auto px-4 sm:px-6 py-10">
        <p className="text-[#6B7085]">Carregando...</p>
      </div>
    );
  }

  if (!rule) {
    return (
      <div className="max-w-3xl mx-auto px-4 sm:px-6 py-12">
        <div className="rounded-3xl bg-[#FFF0F4] border border-[#FE3E6D]/30 p-6">
          <h1 className="text-xl font-semibold text-[#1A1A2E] mb-2">
            Esta aba é para gestores
          </h1>
          <p className="text-sm text-[#1A1A2E]/80">
            Seu acesso ({email ?? "sem e-mail"}) não está mapeado como gestor na
            hierarquia atual. Fale com o time de Design para ajustar, se for o
            caso.
          </p>
        </div>
      </div>
    );
  }

  if (selected) {
    return (
      <GeridoDetail
        response={selected}
        onBack={() => setSelected(null)}
      />
    );
  }

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 py-10 sm:py-14">
      <header className="mb-8">
        <p className="text-xs uppercase tracking-wider text-[#FE3E6D] font-semibold mb-3">
          Geridos · {rule.label}
        </p>
        <h1 className="text-3xl sm:text-4xl font-semibold text-[#1A1A2E] tracking-tight">
          Rodas das pessoas que você gere
        </h1>
        <p className="mt-2 text-[#6B7085] max-w-2xl">
          Mesma leitura que a pessoa recebe: onde ela está hoje e qual o
          próximo passo. Sem nota, sem comparação entre pessoas.
        </p>
      </header>

      {error && (
        <div className="rounded-2xl bg-[#FFF0F4] border border-[#FE3E6D]/30 p-4 text-[#FE3E6D] text-sm mb-6">
          Erro: {error}
        </div>
      )}

      {managed.length === 0 ? (
        <div className="rounded-3xl bg-white border border-[#E6E6EF] p-8 text-center">
          <p className="font-medium text-[#1A1A2E]">
            Ninguém do seu time respondeu ainda.
          </p>
          <p className="text-sm text-[#6B7085] mt-2 max-w-md mx-auto">
            Assim que as pessoas enviarem a roda, elas aparecem aqui.
          </p>
        </div>
      ) : (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {managed.map((r) => {
            const widx = weightedIndex(r.scores, r.discipline as Discipline);
            const lvl = widx != null ? levelOf(widx) : null;
            return (
              <button
                key={r.id}
                onClick={() => setSelected(r)}
                className="text-left bg-white border border-[#E6E6EF] rounded-3xl p-5 hover:border-[#FE3E6D]/50 hover:shadow-sm transition active:scale-[0.99]"
              >
                <p className="font-semibold text-[#1A1A2E] text-lg leading-tight">
                  {r.person_name}
                </p>
                <p className="text-xs text-[#6B7085] mt-1">
                  {r.discipline} · {r.career_level}
                </p>
                {lvl && (
                  <div className="mt-4 inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-[#1A1A2E] text-white text-xs font-medium">
                    Nível {lvl.n} · {lvl.name}
                  </div>
                )}
                <p className="mt-4 text-xs text-[#FE3E6D] font-medium flex items-center gap-0.5">
                  Ver roda <ChevronRight size={12} />
                </p>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

function GeridoDetail({
  response,
  onBack,
}: {
  response: Response;
  onBack: () => void;
}) {
  const discipline = response.discipline as Discipline;
  const widx = weightedIndex(response.scores, discipline);
  const level = widx != null ? levelOf(widx) : null;
  const nextLevelN = level ? Math.min(5, level.n + 1) : null;
  const nextLevel =
    nextLevelN != null ? LEVELS.find((l) => l.n === nextLevelN) ?? null : null;
  const prios = priorities(response.scores, discipline);
  const centerLabel = level ? `Nível ${level.n}` : "—";
  const centerSub = level ? level.name : "";

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 py-10 sm:py-14">
      <button
        onClick={onBack}
        className="mb-6 inline-flex items-center gap-1 px-3 py-1.5 rounded-full bg-[#F0F0F6] hover:bg-[#ECECF4] text-[#1A1A2E] text-sm transition active:scale-95"
      >
        <ChevronLeft size={14} /> Voltar aos geridos
      </button>

      <p className="text-xs uppercase tracking-wider text-[#FE3E6D] font-semibold mb-3">
        Roda de {response.person_name.split(" ")[0]}
      </p>
      <h1 className="text-3xl sm:text-4xl font-semibold text-[#1A1A2E] tracking-tight">
        {response.person_name}
      </h1>
      <p className="mt-2 text-[#6B7085]">
        {response.discipline} · {response.career_level} · enviado em{" "}
        {new Date(response.created_at).toLocaleDateString("pt-BR", {
          day: "2-digit",
          month: "short",
          year: "numeric",
        })}
      </p>

      <div className="mt-8 grid md:grid-cols-[1fr_1fr] gap-8 items-start">
        <div className="bg-white border border-[#E6E6EF] rounded-3xl p-5 flex flex-col items-center">
          <Wheel
            scores={response.scores}
            size={340}
            centerLabel={centerLabel}
            centerSub={centerSub}
          />
          <div className="mt-5 w-full">
            <WheelLegend />
          </div>
        </div>

        <div className="space-y-4">
          {level && (
            <div className="bg-[#1A1A2E] text-white rounded-3xl p-6">
              <p className="text-xs uppercase tracking-wider opacity-70">
                Está em
              </p>
              <p className="text-2xl font-semibold mt-1">
                Nível {level.n} · {level.name}
              </p>
              <p className="text-sm opacity-80 mt-1">{level.persona}</p>
              <p className="text-sm opacity-90 mt-3 leading-relaxed">
                {level.desc}
              </p>
            </div>
          )}
          {nextLevel && nextLevel.n !== level?.n && (
            <div className="bg-[#FFF0F4] border border-[#FE3E6D]/30 rounded-3xl p-6">
              <p className="text-xs uppercase tracking-wider text-[#FE3E6D] font-semibold">
                Próximo passo
              </p>
              <p className="text-2xl font-semibold mt-1 text-[#1A1A2E]">
                Nível {nextLevel.n} · {nextLevel.name}
              </p>
              <p className="text-sm text-[#1A1A2E]/70 mt-1">
                {nextLevel.persona}
              </p>
              <p className="text-sm text-[#1A1A2E]/90 mt-3 leading-relaxed">
                {nextLevel.desc}
              </p>
            </div>
          )}
        </div>
      </div>

      <section className="mt-10">
        <h2 className="text-lg font-semibold text-[#1A1A2E] mb-3">
          Onde está em cada segmento
        </h2>
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {SEGMENTS.map((s) => {
            const avg = segmentAverage(response.scores, s.id);
            const n =
              avg != null ? Math.max(1, Math.min(5, Math.round(avg))) : null;
            const lvl = n != null ? LEVELS.find((l) => l.n === n) : null;
            return (
              <div
                key={s.id}
                className="bg-white border border-[#E6E6EF] rounded-2xl p-4"
              >
                <div className="flex items-center justify-between mb-3">
                  <span
                    className="text-xs font-semibold"
                    style={{ color: s.color }}
                  >
                    {s.id} · {s.short}
                  </span>
                  {n != null ? (
                    <span
                      className="text-xs font-semibold px-2 py-0.5 rounded-full text-white"
                      style={{ background: s.color }}
                    >
                      Nível {n}
                    </span>
                  ) : (
                    <span className="text-xs text-[#6B7085]">—</span>
                  )}
                </div>
                <div className="flex gap-1">
                  {[1, 2, 3, 4, 5].map((k) => (
                    <div
                      key={k}
                      className="flex-1 h-1.5 rounded-full"
                      style={{
                        background: n != null && k <= n ? s.color : "#F0F0F6",
                      }}
                    />
                  ))}
                </div>
                {lvl && (
                  <p className="text-xs text-[#6B7085] mt-3">
                    <span className="text-[#1A1A2E] font-medium">
                      {lvl.name}
                    </span>{" "}
                    · {lvl.persona}
                  </p>
                )}
              </div>
            );
          })}
        </div>
      </section>

      {prios.length > 0 && (
        <section className="mt-10">
          <h2 className="text-lg font-semibold text-[#1A1A2E] mb-1">
            3 pontos para evoluir primeiro
          </h2>
          <p className="text-sm text-[#6B7085] mb-4">
            Insumo para a próxima 1:1. Em cada ponto: a prática atual e o
            próximo passo.
          </p>
          <div className="space-y-3">
            {prios.map((p, i) => {
              const seg = getSegment(p.item.segment);
              const curr = p.item.levels[p.score - 1];
              return (
                <div
                  key={p.item.code}
                  className="bg-white border border-[#E6E6EF] rounded-3xl p-5"
                >
                  <div className="flex items-baseline gap-3 mb-3">
                    <span className="shrink-0 w-7 h-7 rounded-full bg-[#1A1A2E] text-white flex items-center justify-center text-xs font-semibold">
                      {i + 1}
                    </span>
                    <div className="min-w-0">
                      <p
                        className="text-xs font-semibold"
                        style={{ color: seg.color }}
                      >
                        {p.item.code} · {seg.short}
                      </p>
                      <p className="font-semibold text-[#1A1A2E]">
                        {p.item.title}
                      </p>
                    </div>
                  </div>
                  <div className="grid sm:grid-cols-2 gap-3">
                    <div className="rounded-2xl bg-[#F7F7FB] p-3">
                      <p className="text-[10px] uppercase tracking-wider text-[#6B7085] font-semibold mb-1">
                        Está aqui
                      </p>
                      <p className="text-sm text-[#1A1A2E] leading-relaxed">
                        {curr}
                      </p>
